#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// DockSite's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/dock_site.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The step of a keyboard seam move, in logical units; 8 by default. A value outside 1 to 256 throws std::out_of_range and changes nothing.
template <typename Declaring>
struct DockSiteKeyboardIncrementCapability {
    PropertyCell<double, DockSiteKeyboardIncrementCapability<Declaring>> keyboard_increment{8.0};

    static void assign(DockSiteKeyboardIncrementCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.keyboard_increment), incoming);
        if (!capability.keyboard_increment.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.keyboard_increment));
    }
};

// The distance, in logical units along either axis, a caption press moves before it drags (owner decision DK-26, D5-1: 4, or a host's metric; no host reports one yet). A value outside 1 to 64 throws std::out_of_range and changes nothing.
template <typename Declaring>
struct DockSiteDragThresholdCapability {
    PropertyCell<double, DockSiteDragThresholdCapability<Declaring>> drag_threshold{4.0};

    static void assign(DockSiteDragThresholdCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.drag_threshold), incoming);
        if (!capability.drag_threshold.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.drag_threshold));
    }
};

// Every DockSite capability, in the order the declaring class takes them.
template <typename Declaring>
struct DockSiteCapabilities : public DockSiteKeyboardIncrementCapability<Declaring>,
                              public DockSiteDragThresholdCapability<Declaring> {};

} // namespace gui_forms
